70	/*
71	    Parallel sum reduction using shared memory
72	    - takes log(n) steps for n input elements
73	    - uses n threads
74	    - only works for power-of-2 arrays
75	*/
76	
77	/* This reduction interleaves which threads are active by using the modulo
78	   operator.  This operator is very expensive on GPUs, and the interleaved
79	   inactivity means that no whole warps are active, which is also very
80	   inefficient */
81	template <class T>
82	__global__ void reduce0(T *g_idata, T *g_odata, unsigned int n) {
83	  // Handle to thread block group
84	  cg::thread_block cta = cg::this_thread_block();
85	  T *sdata = SharedMemory<T>();
86	
87	  // load shared mem
88	  unsigned int tid = threadIdx.x;
89	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
90	
91	  sdata[tid] = (i < n) ? g_idata[i] : 0;
92	
93	  cg::sync(cta);
94	
95	  // do reduction in shared mem
96	  for (unsigned int s = 1; s < blockDim.x; s *= 2) {
97	    // modulo arithmetic is slow!
98	    if ((tid % (2 * s)) == 0) {
99	      sdata[tid] += sdata[tid + s];
100	    }
101	
102	    cg::sync(cta);
103	  }
104	
105	  // write result for this block to global mem
106	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
107	}
108	
109	/* This version uses contiguous threads, but its interleaved
110	   addressing results in many shared memory bank conflicts.
111	*/
112	template <class T>
113	__global__ void reduce1(T *g_idata, T *g_odata, unsigned int n) {
114	  // Handle to thread block group
115	  cg::thread_block cta = cg::this_thread_block();
116	  T *sdata = SharedMemory<T>();
117	
118	  // load shared mem
119	  unsigned int tid = threadIdx.x;
120	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
121	
122	  sdata[tid] = (i < n) ? g_idata[i] : 0;
123	
124	  cg::sync(cta);
125	
126	  // do reduction in shared mem
127	  for (unsigned int s = 1; s < blockDim.x; s *= 2) {
128	    int index = 2 * s * tid;
129	
130	    if (index < blockDim.x) {
131	      sdata[index] += sdata[index + s];
132	    }
133	
134	    cg::sync(cta);
135	  }
136	
137	  // write result for this block to global mem
138	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
139	}
