141	/*
142	    This version uses sequential addressing -- no divergence or bank conflicts.
143	*/
144	template <class T>
145	__global__ void reduce2(T *g_idata, T *g_odata, unsigned int n) {
146	  // Handle to thread block group
147	  cg::thread_block cta = cg::this_thread_block();
148	  T *sdata = SharedMemory<T>();
149	
150	  // load shared mem
151	  unsigned int tid = threadIdx.x;
152	  unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
153	
154	  sdata[tid] = (i < n) ? g_idata[i] : 0;
155	
156	  cg::sync(cta);
157	
158	  // do reduction in shared mem
159	  for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
160	    if (tid < s) {
161	      sdata[tid] += sdata[tid + s];
162	    }
163	
164	    cg::sync(cta);
165	  }
166	
167	  // write result for this block to global mem
168	  if (tid == 0) g_odata[blockIdx.x] = sdata[0];
169	}
