406	////////////////////////////////////////////////////////////////////////////////
407	// Wrapper function for kernel launch
408	////////////////////////////////////////////////////////////////////////////////
409	template <class T>
410	void reduce(int size, int threads, int blocks, int whichKernel, T *d_idata,
411	            T *d_odata) {
412	  dim3 dimBlock(threads, 1, 1);
413	  dim3 dimGrid(blocks, 1, 1);
414	
415	  // when there is only one warp per block, we need to allocate two warps
416	  // worth of shared memory so that we don't index shared memory out of bounds
417	  int smemSize =
418	      (threads <= 32) ? 2 * threads * sizeof(T) : threads * sizeof(T);
419	
420	  // choose which of the optimized versions of reduction to launch
421	  switch (whichKernel) {
422	    case 0:
423	      reduce0<T><<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
424	      break;
425	
426	    case 1:
427	      reduce1<T><<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
428	      break;
429	
430	    case 2:
431	      reduce2<T><<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
432	      break;
433	
434	    case 3:
435	      reduce3<T><<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
436	      break;
437	
438	    case 4:
439	      switch (threads) {
440	        case 512:
441	          reduce4<T, 512>
442	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
443	          break;
444	
445	        case 256:
446	          reduce4<T, 256>
447	              <<<dimGrid, dimBlock, smemSize>>>(d_idata, d_odata, size);
448	          break;
449	
450	        case 128:
