28	/*
29	    Parallel reduction
30	
31	    This sample shows how to perform a reduction operation on an array of values
32	    to produce a single value.
33	
34	    Reductions are a very common computation in parallel algorithms.  Any time
35	    an array of values needs to be reduced to a single value using a binary
36	    associative operator, a reduction can be used.  Example applications include
37	    statistics computations such as mean and standard deviation, and image
38	    processing applications such as finding the total luminance of an
39	    image.
40	
41	    This code performs sum reductions, but any associative operator such as
42	    min() or max() could also be used.
43	
44	    It assumes the input size is a power of 2.
45	
46	    COMMAND LINE ARGUMENTS
47	
48	    "--shmoo":         Test performance for 1 to 32M elements with each of the 7
49	   different kernels
50	    "--n=<N>":         Specify the number of elements to reduce (default
51	   1048576)
52	    "--threads=<N>":   Specify the number of threads per block (default 128)
53	    "--kernel=<N>":    Specify which kernel to run (0-6, default 6)
54	    "--maxblocks=<N>": Specify the maximum number of thread blocks to launch
55	   (kernel 6 only, default 64)
56	    "--cpufinal":      Read back the per-block results and do final sum of block
57	   sums on CPU (default false)
58	    "--cputhresh=<N>": The threshold of number of blocks sums below which to
59	   perform a CPU final reduction (default 1)
60	    "-type=<T>":       The datatype for the reduction, where T is "int",
61	   "float", or "double" (default int)
62	*/
63	
64	// CUDA Runtime
65	#include <cuda_runtime.h>
66	
67	// Utilities and system includes
68	#include <helper_cuda.h>
69	#include <helper_functions.h>
70	#include <algorithm>
71	
72	// includes, project
73	#include "reduction.h"
74	
75	enum ReduceType { REDUCE_INT, REDUCE_FLOAT, REDUCE_DOUBLE };
76	
77	////////////////////////////////////////////////////////////////////////////////
78	// declaration, forward
79	template <class T>
80	bool runTest(int argc, char **argv, ReduceType datatype);
81	
82	#define MAX_BLOCK_DIM_SIZE 65535
83	
84	#ifdef WIN32
85	#define strcasecmp strcmpi
86	#endif
87	
88	extern "C" bool isPow2(unsigned int x) { return ((x & (x - 1)) == 0); }
89	
90	const char *getReduceTypeString(const ReduceType type) {
91	  switch (type) {
92	    case REDUCE_INT:
93	      return "int";
94	    case REDUCE_FLOAT:
95	      return "float";
96	    case REDUCE_DOUBLE:
97	      return "double";
98	    default:
99	      return "unknown";
100	  }
101	}
102	
103	////////////////////////////////////////////////////////////////////////////////
104	// Program main
105	////////////////////////////////////////////////////////////////////////////////
106	int main(int argc, char **argv) {
107	  printf("%s Starting...\n\n", argv[0]);
108	
109	  char *typeInput = 0;
110	  getCmdLineArgumentString(argc, (const char **)argv, "type", &typeInput);
111	
112	  ReduceType datatype = REDUCE_INT;
113	
114	  if (0 != typeInput) {
115	    if (!strcasecmp(typeInput, "float")) {
116	      datatype = REDUCE_FLOAT;
117	    } else if (!strcasecmp(typeInput, "double")) {
118	      datatype = REDUCE_DOUBLE;
119	    } else if (strcasecmp(typeInput, "int")) {
120	      printf("Type %s is not recognized. Using default type int.\n\n",
121	             typeInput);
122	    }
123	  }
124	
125	  cudaDeviceProp deviceProp;
126	  int dev;
127	
128	  dev = findCudaDevice(argc, (const char **)argv);
129	
130	  checkCudaErrors(cudaGetDeviceProperties(&deviceProp, dev));
131	
132	  printf("Using Device %d: %s\n\n", dev, deviceProp.name);
133	  checkCudaErrors(cudaSetDevice(dev));
134	
135	  printf("Reducing array of type %s\n\n", getReduceTypeString(datatype));
136	
137	  bool bResult = false;
138	
139	  switch (datatype) {
140	    default:
141	    case REDUCE_INT:
142	      bResult = runTest<int>(argc, argv, datatype);
143	      break;
144	
145	    case REDUCE_FLOAT:
146	      bResult = runTest<float>(argc, argv, datatype);
147	      break;
148	
149	    case REDUCE_DOUBLE:
150	      bResult = runTest<double>(argc, argv, datatype);
151	      break;
152	  }
153	
154	  printf(bResult ? "Test passed\n" : "Test failed!\n");
155	}
156	
157	////////////////////////////////////////////////////////////////////////////////
158	//! Compute sum reduction on CPU
159	//! We use Kahan summation for an accurate sum of large arrays.
160	//! http://en.wikipedia.org/wiki/Kahan_summation_algorithm
161	//!
162	//! @param data       pointer to input data
163	//! @param size       number of input data elements
164	////////////////////////////////////////////////////////////////////////////////
165	template <class T>
166	T reduceCPU(T *data, int size) {
167	  T sum = data[0];
168	  T c = (T)0.0;
169	
170	  for (int i = 1; i < size; i++) {
171	    T y = data[i] - c;
172	    T t = sum + y;
173	    c = (t - sum) - y;
174	    sum = t;
175	  }
176	
177	  return sum;
178	}
179	
180	unsigned int nextPow2(unsigned int x) {
181	  --x;
182	  x |= x >> 1;
183	  x |= x >> 2;
184	  x |= x >> 4;
185	  x |= x >> 8;
186	  x |= x >> 16;
187	  return ++x;
188	}
189	
190	#ifndef MIN
191	#define MIN(x, y) ((x < y) ? x : y)
192	#endif
193	
194	////////////////////////////////////////////////////////////////////////////////
195	// Compute the number of threads and blocks to use for the given reduction
196	// kernel For the kernels >= 3, we set threads / block to the minimum of
197	// maxThreads and n/2. For kernels < 3, we set to the minimum of maxThreads and
198	// n.  For kernel 6, we observe the maximum specified number of blocks, because
199	// each thread in that kernel can process a variable number of elements.
200	////////////////////////////////////////////////////////////////////////////////
201	void getNumBlocksAndThreads(int whichKernel, int n, int maxBlocks,
202	                            int maxThreads, int &blocks, int &threads) {
203	  // get device capability, to avoid block/grid size exceed the upper bound
204	  cudaDeviceProp prop;
205	  int device;
206	  checkCudaErrors(cudaGetDevice(&device));
207	  checkCudaErrors(cudaGetDeviceProperties(&prop, device));
208	
209	  if (whichKernel < 3) {
210	    threads = (n < maxThreads) ? nextPow2(n) : maxThreads;
211	    blocks = (n + threads - 1) / threads;
212	  } else {
213	    threads = (n < maxThreads * 2) ? nextPow2((n + 1) / 2) : maxThreads;
214	    blocks = (n + (threads * 2 - 1)) / (threads * 2);
215	  }
216	
217	  if ((float)threads * blocks >
218	      (float)prop.maxGridSize[0] * prop.maxThreadsPerBlock) {
219	    printf("n is too large, please choose a smaller number!\n");
220	  }
221	
222	  if (blocks > prop.maxGridSize[0]) {
223	    printf(
224	        "Grid size <%d> exceeds the device capability <%d>, set block size as "
225	        "%d (original %d)\n",
226	        blocks, prop.maxGridSize[0], threads * 2, threads);
227	
228	    blocks /= 2;
229	    threads *= 2;
230	  }
231	
232	  if (whichKernel == 6) {
233	    blocks = MIN(maxBlocks, blocks);
234	  }
235	}
236	
237	////////////////////////////////////////////////////////////////////////////////
238	// This function performs a reduction of the input data multiple times and
239	// measures the average reduction time.
240	////////////////////////////////////////////////////////////////////////////////
241	template <class T>
242	T benchmarkReduce(int n, int numThreads, int numBlocks, int maxThreads,
243	                  int maxBlocks, int whichKernel, int testIterations,
244	                  bool cpuFinalReduction, int cpuFinalThreshold,
245	                  StopWatchInterface *timer, T *h_odata, T *d_idata,
246	                  T *d_odata) {
247	  T gpu_result = 0;
248	  bool needReadBack = true;
249	
250	  T *d_intermediateSums;
251	  checkCudaErrors(
252	      cudaMalloc((void **)&d_intermediateSums, sizeof(T) * numBlocks));
253	
254	  for (int i = 0; i < testIterations; ++i) {
255	    gpu_result = 0;
256	
257	    cudaDeviceSynchronize();
258	    sdkStartTimer(&timer);
259	
260	    // execute the kernel
261	    reduce<T>(n, numThreads, numBlocks, whichKernel, d_idata, d_odata);
262	
263	    // check if kernel execution generated an error
264	    getLastCudaError("Kernel execution failed");
265	
266	    if (cpuFinalReduction) {
267	      // sum partial sums from each block on CPU
268	      // copy result from device to host
269	      checkCudaErrors(cudaMemcpy(h_odata, d_odata, numBlocks * sizeof(T),
270	                                 cudaMemcpyDeviceToHost));
271	
272	      for (int i = 0; i < numBlocks; i++) {
273	        gpu_result += h_odata[i];
274	      }
275	
276	      needReadBack = false;
277	    } else {
278	      // sum partial block sums on GPU
279	      int s = numBlocks;
280	      int kernel = whichKernel;
281	
282	      while (s > cpuFinalThreshold) {
283	        int threads = 0, blocks = 0;
284	        getNumBlocksAndThreads(kernel, s, maxBlocks, maxThreads, blocks,
285	                               threads);
286	        checkCudaErrors(cudaMemcpy(d_intermediateSums, d_odata, s * sizeof(T),
287	                                   cudaMemcpyDeviceToDevice));
288	        reduce<T>(s, threads, blocks, kernel, d_intermediateSums, d_odata);
289	
290	        if (kernel < 3) {
291	          s = (s + threads - 1) / threads;
292	        } else {
293	          s = (s + (threads * 2 - 1)) / (threads * 2);
294	        }
295	      }
296	
297	      if (s > 1) {
298	        // copy result from device to host
299	        checkCudaErrors(cudaMemcpy(h_odata, d_odata, s * sizeof(T),
300	                                   cudaMemcpyDeviceToHost));
301	
302	        for (int i = 0; i < s; i++) {
303	          gpu_result += h_odata[i];
304	        }
305	
306	        needReadBack = false;
307	      }
308	    }
309	
310	    cudaDeviceSynchronize();
311	    sdkStopTimer(&timer);
312	  }
313	
314	  if (needReadBack) {
315	    // copy final sum from device to host
316	    checkCudaErrors(
317	        cudaMemcpy(&gpu_result, d_odata, sizeof(T), cudaMemcpyDeviceToHost));
318	  }
319	  checkCudaErrors(cudaFree(d_intermediateSums));
320	  return gpu_result;
321	}
322	
323	////////////////////////////////////////////////////////////////////////////////
324	// This function calls benchmarkReduce multiple times for a range of array sizes
325	// and prints a report in CSV (comma-separated value) format that can be used
326	// for generating a "shmoo" plot showing the performance for each kernel
327	// variation over a wide range of input sizes.
328	////////////////////////////////////////////////////////////////////////////////
329	template <class T>
330	void shmoo(int minN, int maxN, int maxThreads, int maxBlocks,
331	           ReduceType datatype) {
332	  // create random input data on CPU
333	  unsigned int bytes = maxN * sizeof(T);
334	
335	  T *h_idata = (T *)malloc(bytes);
336	
337	  for (int i = 0; i < maxN; i++) {
338	    // Keep the numbers small so we don't get truncation error in the sum
339	    if (datatype == REDUCE_INT) {
340	      h_idata[i] = (T)(rand() & 0xFF);
341	    } else {
342	      h_idata[i] = (rand() & 0xFF) / (T)RAND_MAX;
343	    }
344	  }
345	
346	  int maxNumBlocks = MIN(maxN / maxThreads, MAX_BLOCK_DIM_SIZE);
347	
348	  // allocate mem for the result on host side
349	  T *h_odata = (T *)malloc(maxNumBlocks * sizeof(T));
350	
351	  // allocate device memory and data
352	  T *d_idata = NULL;
353	  T *d_odata = NULL;
354	
355	  checkCudaErrors(cudaMalloc((void **)&d_idata, bytes));
356	  checkCudaErrors(cudaMalloc((void **)&d_odata, maxNumBlocks * sizeof(T)));
357	
358	  // copy data directly to device memory
359	  checkCudaErrors(cudaMemcpy(d_idata, h_idata, bytes, cudaMemcpyHostToDevice));
360	  checkCudaErrors(cudaMemcpy(d_odata, h_idata, maxNumBlocks * sizeof(T),
361	                             cudaMemcpyHostToDevice));
362	
363	  // warm-up
364	  for (int kernel = 0; kernel < 7; kernel++) {
365	    reduce<T>(maxN, maxThreads, maxNumBlocks, kernel, d_idata, d_odata);
366	  }
367	
368	  int testIterations = 100;
369	
370	  StopWatchInterface *timer = 0;
371	  sdkCreateTimer(&timer);
372	
373	  // print headers
374	  printf(
375	      "Time in milliseconds for various numbers of elements for each "
376	      "kernel\n\n\n");
377	  printf("Kernel");
378	
379	  for (int i = minN; i <= maxN; i *= 2) {
380	    printf(", %d", i);
381	  }
382	
383	  for (int kernel = 0; kernel < 7; kernel++) {
384	    printf("\n%d", kernel);
385	
386	    for (int i = minN; i <= maxN; i *= 2) {
387	      sdkResetTimer(&timer);
388	      int numBlocks = 0;
389	      int numThreads = 0;
390	      getNumBlocksAndThreads(kernel, i, maxBlocks, maxThreads, numBlocks,
391	                             numThreads);
392	
393	      float reduceTime;
394	
395	      if (numBlocks <= MAX_BLOCK_DIM_SIZE) {
396	        benchmarkReduce(i, numThreads, numBlocks, maxThreads, maxBlocks, kernel,
397	                        testIterations, false, 1, timer, h_odata, d_idata,
398	                        d_odata);
399	        reduceTime = sdkGetAverageTimerValue(&timer);
400	      } else {
401	        reduceTime = -1.0;
402	      }
403	
404	      printf(", %.5f", reduceTime);
405	    }
406	  }
407	
408	  // cleanup
409	  sdkDeleteTimer(&timer);
410	  free(h_idata);
411	  free(h_odata);
412	
413	  checkCudaErrors(cudaFree(d_idata));
414	  checkCudaErrors(cudaFree(d_odata));
415	}
416	
417	////////////////////////////////////////////////////////////////////////////////
418	// The main function which runs the reduction test.
419	////////////////////////////////////////////////////////////////////////////////
420	template <class T>
421	bool runTest(int argc, char **argv, ReduceType datatype) {
422	  int size = 1 << 24;    // number of elements to reduce
423	  int maxThreads = 256;  // number of threads per block
424	  int whichKernel = 3;
425	  int maxBlocks = 64;
426	  bool cpuFinalReduction = false;
427	  int cpuFinalThreshold = 1;
428	
429	  if (checkCmdLineFlag(argc, (const char **)argv, "n")) {
430	    size = getCmdLineArgumentInt(argc, (const char **)argv, "n");
431	  }
432	
433	  if (checkCmdLineFlag(argc, (const char **)argv, "threads")) {
434	    maxThreads = getCmdLineArgumentInt(argc, (const char **)argv, "threads");
435	  }
436	
437	  if (checkCmdLineFlag(argc, (const char **)argv, "kernel")) {
438	    whichKernel = getCmdLineArgumentInt(argc, (const char **)argv, "kernel");
439	  }
440	
441	  if (checkCmdLineFlag(argc, (const char **)argv, "maxblocks")) {
442	    maxBlocks = getCmdLineArgumentInt(argc, (const char **)argv, "maxblocks");
443	  }
444	
445	  printf("%d elements\n", size);
446	  printf("%d threads (max)\n", maxThreads);
447	
448	  cpuFinalReduction = checkCmdLineFlag(argc, (const char **)argv, "cpufinal");
449	
450	  if (checkCmdLineFlag(argc, (const char **)argv, "cputhresh")) {
451	    cpuFinalThreshold =
452	        getCmdLineArgumentInt(argc, (const char **)argv, "cputhresh");
453	  }
454	
455	  bool runShmoo = checkCmdLineFlag(argc, (const char **)argv, "shmoo");
456	
457	  if (runShmoo) {
458	    shmoo<T>(1, 33554432, maxThreads, maxBlocks, datatype);
459	  } else {
460	    // create random input data on CPU
461	    unsigned int bytes = size * sizeof(T);
462	
463	    T *h_idata = (T *)malloc(bytes);
464	
465	    for (int i = 0; i < size; i++) {
466	      // Keep the numbers small so we don't get truncation error in the sum
467	      if (datatype == REDUCE_INT) {
468	        h_idata[i] = (T)(rand() & 0xFF);
469	      } else {
470	        h_idata[i] = (rand() & 0xFF) / (T)RAND_MAX;
471	      }
472	    }
473	
474	    int numBlocks = 0;
475	    int numThreads = 0;
476	    getNumBlocksAndThreads(whichKernel, size, maxBlocks, maxThreads, numBlocks,
477	                           numThreads);
478	
479	    if (numBlocks == 1) {
480	      cpuFinalThreshold = 1;
481	    }
482	
483	    // allocate mem for the result on host side
484	    T *h_odata = (T *)malloc(numBlocks * sizeof(T));
485	
486	    printf("%d blocks\n\n", numBlocks);
487	
488	    // allocate device memory and data
489	    T *d_idata = NULL;
490	    T *d_odata = NULL;
491	
492	    checkCudaErrors(cudaMalloc((void **)&d_idata, bytes));
493	    checkCudaErrors(cudaMalloc((void **)&d_odata, numBlocks * sizeof(T)));
494	
495	    // copy data directly to device memory
496	    checkCudaErrors(
497	        cudaMemcpy(d_idata, h_idata, bytes, cudaMemcpyHostToDevice));
498	    checkCudaErrors(cudaMemcpy(d_odata, h_idata, numBlocks * sizeof(T),
499	                               cudaMemcpyHostToDevice));
500	
501	    // warm-up
502	    reduce<T>(size, numThreads, numBlocks, whichKernel, d_idata, d_odata);
503	
504	    int testIterations = 100;
505	
506	    StopWatchInterface *timer = 0;
507	    sdkCreateTimer(&timer);
508	
509	    T gpu_result = 0;
510	
511	    gpu_result =
512	        benchmarkReduce<T>(size, numThreads, numBlocks, maxThreads, maxBlocks,
513	                           whichKernel, testIterations, cpuFinalReduction,
514	                           cpuFinalThreshold, timer, h_odata, d_idata, d_odata);
515	
516	    double reduceTime = sdkGetAverageTimerValue(&timer) * 1e-3;
517	    printf(
518	        "Reduction, Throughput = %.4f GB/s, Time = %.5f s, Size = %u Elements, "
519	        "NumDevsUsed = %d, Workgroup = %u\n",
520	        1.0e-9 * ((double)bytes) / reduceTime, reduceTime, size, 1, numThreads);
521	
522	    // compute reference solution
523	    T cpu_result = reduceCPU<T>(h_idata, size);
524	
525	    int precision = 0;
526	    double threshold = 0;
527	    double diff = 0;
528	
529	    if (datatype == REDUCE_INT) {
530	      printf("\nGPU result = %d\n", (int)gpu_result);
531	      printf("CPU result = %d\n\n", (int)cpu_result);
532	    } else {
533	      if (datatype == REDUCE_FLOAT) {
534	        precision = 8;
535	        threshold = 1e-8 * size;
536	      } else {
537	        precision = 12;
538	        threshold = 1e-12 * size;
539	      }
540	
541	      printf("\nGPU result = %.*f\n", precision, (double)gpu_result);
542	      printf("CPU result = %.*f\n\n", precision, (double)cpu_result);
543	
544	      diff = fabs((double)gpu_result - (double)cpu_result);
545	    }
546	
547	    // cleanup
548	    sdkDeleteTimer(&timer);
549	    free(h_idata);
550	    free(h_odata);
551	
552	    checkCudaErrors(cudaFree(d_idata));
553	    checkCudaErrors(cudaFree(d_odata));
554	
555	    if (datatype == REDUCE_INT) {
556	      return (gpu_result == cpu_result);
557	    } else {
558	      return (diff < threshold);
559	    }
560	  }
561	
562	  return true;
563	}
